char *create_private_key() {
    RSA *rsa = RSA_new();
    char *key = NULL;
    BIO *bio = NULL;
    int ret = 0;

    if (!rsa) {
        return NULL;
    }

    rsa = RSA_generate_key(2048, RSA_F4, NULL, NULL);
    if (!rsa) {
        RSA_free(rsa);
        return NULL;
    }

    bio = BIO_new(BIO_s_mem());
    if (!bio) {
        RSA_free(rsa);
        return NULL;
    }

    ret = PEM_write_bio_RSAPrivateKey(bio, rsa, NULL, NULL, 0, NULL, NULL);
    if (ret <= 0) {
        RSA_free(rsa);
        BIO_free(bio);
        return NULL;
    }

    long len = BIO_get_length(bio);
    if (len <= 0) {
        BIO_free(bio);
        RSA_free(rsa);
        return NULL;
    }

    key = (char *)malloc(len + 1);
    if (!key) {
        BIO_free(bio);
        RSA_free(rsa);
        return NULL;
    }

    int read_len = BIO_read(bio, key, len);
    if (read_len != len) {
        free(key);
        BIO_free(bio);
        RSA_free(rsa);
        return NULL;
    }

    key[len] = '\0';
    BIO_free(bio);
    RSA_free(rsa);

    return key;
}
